// Replace this node with the call to Brittany's ChatGPT work-order skill.
// It must return the drafted work-order fields — it must NOT send anything to the subcontractor.
// Until it is wired up, the bid is passed through unchanged so the approval loop can be tested end to end.
const b = $('Bid received (POST /webhook/mow-sub-bid)').first().json.body || {};
return [{ json: {
  subject: b.subject || ('Work order — ' + (b.vendor || 'vendor') + ' — ' + (b.job || 'job')),
  vendor_id: b.vendor_id || null,
  home_id: b.home_id || null,
  amount: b.amount || null,
  evidence: b.evidence || b.file || 'bid received by webhook',
  draft: b.draft || { vendor: b.vendor, job: b.job, cost_code: b.cost_code, description: b.description, amount: b.amount, draws: b.draws }
} }];
